```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time::VARCHAR t, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search-%' AND metric IN ('k8s.container.ready','k8s.container.restarts') ORDER BY time",
          "claim": "Search pod stays not-ready (ready=0) through the abnormal window while its restart count climbs from 3 to 6."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name='search' GROUP BY 1",
          "claim": "Search emits no server or client spans in the abnormal period, versus about 1,000 server spans in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind k, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE span_name='search.Search/Nearby' GROUP BY ALL",
          "claim": "Every frontend call to search.Search/Nearby in the abnormal period (780 of 780) ends in Error."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) av FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search-%' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1",
          "claim": "Search CPU and memory stay low in the abnormal period, so the failure is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind k, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND (span_name='HTTP /hotels' OR span_name='search.Search/Nearby') GROUP BY ALL",
          "claim": "All 780 frontend HTTP /hotels requests return 500, and every one of their search.Search/Nearby child calls errors."
        }
      ]
    }
  ]
}
```

